import Foundation

/// The SF Symbols offered for categories and tags: a curated set suited to
/// torrent collections, plus every symbol name bundled in
/// `SFSymbolNames.txt` (generated by `scripts/make-symbol-list.py`) for search.
enum SymbolCatalog {
    static let curated: [String] = [
        "folder.fill", "tray.full.fill", "archivebox.fill", "shippingbox.fill", "externaldrive.fill", "internaldrive.fill",
        "server.rack", "opticaldisc.fill", "film.fill", "film.stack.fill", "popcorn.fill", "tv.fill", "play.tv.fill",
        "play.rectangle.fill", "theatermasks.fill", "ticket.fill", "music.note", "music.note.list", "headphones", "music.mic",
        "mic.fill", "book.fill", "books.vertical.fill", "book.closed.fill", "newspaper.fill", "doc.fill", "doc.text.fill",
        "photo.fill", "photo.on.rectangle.angled", "camera.fill", "paintpalette.fill", "gamecontroller.fill", "puzzlepiece.fill",
        "app.fill", "square.stack.3d.up.fill", "cpu.fill", "desktopcomputer", "laptopcomputer", "apple.terminal.fill",
        "chevron.left.forwardslash.chevron.right", "wrench.and.screwdriver.fill", "hammer.fill", "globe", "globe.americas.fill",
        "network", "link", "antenna.radiowaves.left.and.right", "graduationcap.fill", "briefcase.fill", "cart.fill", "gift.fill",
        "heart.fill", "star.fill", "flag.fill", "bookmark.fill", "tag.fill", "pin.fill", "bolt.fill", "flame.fill", "leaf.fill",
        "sparkles", "moon.fill", "sun.max.fill", "cloud.fill", "clock.fill", "calendar", "hourglass", "arrow.down.circle.fill",
        "checkmark.seal.fill", "lock.fill", "eye.fill", "person.fill", "person.2.fill", "figure.run", "sportscourt.fill",
        "airplane", "car.fill", "house.fill", "building.2.fill", "map.fill", "flask.fill", "atom", "function",
        "dollarsign.circle.fill", "bitcoinsign.circle.fill", "exclamationmark.triangle.fill", "questionmark.folder.fill",
        "trash.fill",
    ]

    /// Every bundled symbol name (about 7,500). Read on demand by the picker's search and
    /// released with it, so nothing stays in memory while no picker is open.
    nonisolated static func loadAll() -> [String] {
        guard let url = Bundle.main.url(forResource: "SFSymbolNames", withExtension: "txt"),
              let text = try? String(contentsOf: url, encoding: .utf8) else { return curated }
        return text.split(separator: "\n").map(String.init)
    }

    /// Names matching every word of `query` (dots, dashes and spaces separate words), the
    /// curated ones first, then shorter (base) names before their variants.
    nonisolated static func search(_ query: String, in names: [String], limit: Int = 400) -> [String] {
        let words = query.lowercased().split { $0 == " " || $0 == "." || $0 == "-" }.map(String.init)
        guard !words.isEmpty else { return curated }
        let curatedSet = Set(curated)
        let matches = names.filter { name in words.allSatisfy { name.contains($0) } }
        let ranked = matches.sorted { lhs, rhs in
            let lhsCurated = curatedSet.contains(lhs), rhsCurated = curatedSet.contains(rhs)
            if lhsCurated != rhsCurated { return lhsCurated }
            if lhs.count != rhs.count { return lhs.count < rhs.count }
            return lhs < rhs
        }
        return Array(ranked.prefix(limit))
    }
}
